-- A whole number in range; CASE so a string returns false, not a cast error.
create or replace function public.contract_whole(p jsonb,p_min numeric,p_max numeric) returns boolean
language sql immutable set search_path='' as $$
  select case when jsonb_typeof(p)='number'
    then (p::text)::numeric=trunc((p::text)::numeric) and (p::text)::numeric between p_min and p_max
    else false end;
$$;

create or replace function public.contract_str_in(p jsonb,p_list jsonb) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(jsonb_typeof(p)='string' and p_list ? (p#>>'{}'),false);
$$;

-- A non-empty array of distinct strings drawn from p_list.
create or replace function public.contract_subset(p jsonb,p_list jsonb) returns boolean
language sql immutable set search_path='' as $$
  select case when jsonb_typeof(p)='array' then jsonb_array_length(p)>0
    and not exists(select 1 from jsonb_array_elements(p) e where not public.contract_str_in(e,p_list))
    and (select count(distinct e) from jsonb_array_elements(p) e)=jsonb_array_length(p)
    else false end;
$$;

create or replace function public.contract_date(p jsonb) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(jsonb_typeof(p)='string'
    and (p#>>'{}') ~ (public.parking_contract()->'date'->>'pattern')
    and pg_input_is_valid(p#>>'{}','date'),false);
$$;

-- days, from and to of a schedule slot or a fee period; leaving out both
-- from and to means all day.
create or replace function public.contract_slot_times(p jsonb) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(case when jsonb_typeof(p->'days')='string'
      then public.contract_str_in(p->'days',public.parking_contract()->'time'->'days')
      else public.contract_subset(p->'days',public.parking_contract()->'time'->'weekdays') end
    and (not p ?| array(select jsonb_array_elements_text(public.parking_contract()->'time'->'optional_pair'))
    or jsonb_typeof(p->'from')='string' and jsonb_typeof(p->'to')='string'
    and (p->>'from') ~ (public.parking_contract()->'time'->>'pattern')
    and (p->>'to') ~ (public.parking_contract()->'time'->>'pattern')
    and p->>'from'<>p->>'to'),false);
$$;

-- An object with only the listed keys, and all of them except the optional
-- from/to pair, which contract_slot_times checks.
create or replace function public.contract_slot_keys(p jsonb,p_keys jsonb) returns boolean
language sql immutable set search_path='' as $$
  select case when jsonb_typeof(p)='object' then
    not exists(select 1 from jsonb_object_keys(p) k where not p_keys ? k)
    and not exists(select 1 from jsonb_array_elements_text(p_keys) k
      where not p ? k and not public.parking_contract()->'time'->'optional_pair' ? k)
    else false end;
$$;

-- ===== 停放條件：valid_condition()、condition_space_type()（C2 複製本段與共用段） =====

-- A limit's periods (#188 layer 2, condition.limits.<kind>.periods): 1 to
-- max_entries slots of the listed keys (all but the optional from/to pair
-- required), their days and times as a schedule slot's, each range a whole
-- number within it.
create or replace function public.contract_limit_periods(p jsonb,p_spec jsonb) returns boolean
language sql immutable set search_path='' as $$
  select case when jsonb_typeof(p)='array' then jsonb_array_length(p) between 1 and (p_spec->>'max_entries')::integer
    and not exists(select 1 from jsonb_array_elements(p) e
      where not public.contract_slot_keys(e,p_spec->'keys') or not public.contract_slot_times(e)
        or exists(select 1 from jsonb_each(coalesce(p_spec->'ranges','{}'::jsonb)) r
          where not public.contract_whole(e->r.key,(r.value->>'min')::numeric,(r.value->>'max')::numeric)))
    else false end;
$$;

-- A bay's or a zone's condition (§1.2, §4.3), the same rules as
-- validCondition in validate.ts and lib/models/parking_condition.dart.
create or replace function public.valid_condition(p_condition jsonb,p_zone boolean default false) returns boolean
language plpgsql immutable set search_path='' as $$
declare
  p jsonb:=p_condition;
  c jsonb:=public.parking_contract()->'condition';
  l jsonb; v jsonb; spec jsonb; f record; kinds text[]:='{}';
begin
  if jsonb_typeof(p) is distinct from 'object' or p='{}'::jsonb then return false; end if;
  if exists(select 1 from jsonb_object_keys(p) k
      where not (c->'keys' ? k or (p_zone and c->'zone_keys' ? k))) then return false; end if;
  if (p ? 'bay' and not public.contract_str_in(p->'bay',c->'bay'))
    or (p ? 'use' and not public.contract_str_in(p->'use',c->'use'))
    or (p ? 'share' and not (jsonb_typeof(p->'share')='string' and c->'share' ? (p->>'share')))
    or (p ? 'charge' and not public.contract_str_in(p->'charge',c->'charge')) then return false; end if;
  if not p_zone and not p ? 'bay' then return false; end if;
  if (p ? 'share')<>coalesce(p->>'use'='share',false) then return false; end if;
  if p ? 'share' and (p->>'bay') is distinct from (c->'share'->>(p->>'share')) then return false; end if;

  if p ? 'limits' then
    if jsonb_typeof(p->'limits') is distinct from 'array'
      or jsonb_array_length(p->'limits') not between 1 and (select count(*) from jsonb_object_keys(c->'limits'))
    then return false; end if;
    for l in select e from jsonb_array_elements(p->'limits') e loop
      if jsonb_typeof(l) is distinct from 'object' or jsonb_typeof(l->'kind') is distinct from 'string'
        or not c->'limits' ? (l->>'kind') or (l->>'kind')=any(kinds) then return false; end if;
      kinds:=kinds||(l->>'kind');
      spec:=c->'limits'->(l->>'kind');
      for f in select key,value from jsonb_each(l) loop
        continue when f.key='kind';
        -- Time periods (#188 layer 2): time_limit's and no_parking's.
        if f.key='periods' and spec ? 'periods' then
          if not public.contract_limit_periods(f.value,spec->'periods') then return false; end if;
          continue;
        end if;
        continue when spec->'required' ? f.key;
        if not spec->'optional' ? f.key or not public.contract_whole(f.value,
            (spec->'optional'->f.key->>'min')::numeric,(spec->'optional'->f.key->>'max')::numeric)
        then return false; end if;
      end loop;
      if exists(select 1 from jsonb_array_elements_text(spec->'required') r where not l ? r) then return false; end if;
      if spec ? 'exclusive' and l ?& array(select jsonb_array_elements_text(spec->'exclusive')) then return false; end if;
      if l ? 'vehicle' and not public.contract_str_in(l->'vehicle',c->'special_vehicles') then return false; end if;
    end loop;
  end if;
  if not p_zone and p->>'bay'='motorcycle' and not p ? 'charge'
    and not kinds && array(select jsonb_array_elements_text(c->'street_charge_optional_with'))
  then return false; end if;

  if p ? 'allow' then
    v:=p->'allow';
    if jsonb_typeof(v) is distinct from 'object' or v='{}'::jsonb
      -- A value is true, false or not_stated (#201, eligibility.not_stated).
      or exists(select 1 from jsonb_each(v) e where not c->'allow_keys' ? e.key
        or (jsonb_typeof(e.value)<>'boolean' and e.value is distinct from public.parking_contract()->'eligibility'->'not_stated'))
    then return false; end if;
    if v->'scooter'='true'::jsonb and p->>'bay'='heavy' then return false; end if;
  end if;

  if p ? 'schedule' then
    if jsonb_typeof(p->'schedule') is distinct from 'array'
      or jsonb_array_length(p->'schedule') not between 1 and (c->'schedule'->>'max_entries')::integer
    then return false; end if;
    for l in select e from jsonb_array_elements(p->'schedule') e loop
      if not public.contract_slot_keys(l,c->'schedule'->'keys') or not public.contract_slot_times(l)
        or not public.contract_subset(l->'vehicles',c->'schedule'->'vehicles') then return false; end if;
    end loop;
  end if;

  if p ? 'basis' then
    v:=p->'basis';
    if jsonb_typeof(v) is distinct from 'object'
      or exists(select 1 from jsonb_object_keys(v) k where not c->'basis'->'keys' ? k) then return false; end if;
    -- Reserved until photo evidence ships (verification plan P2).
    if exists(select 1 from jsonb_array_elements_text(c->'basis'->'reserved') r
        where coalesce(jsonb_typeof(v->r),'null')<>'null') then return false; end if;
    if not exists(select 1 from jsonb_array_elements_text(c->'basis'->'required_one_of') r
        where coalesce(jsonb_typeof(v->r),'null')<>'null') then return false; end if;
    if v ? 'source_url' and not coalesce(jsonb_typeof(v->'source_url')='string'
        -- UTF-16 code units, as Dart and JS count: characters outside the BMP count twice.
        and char_length(v->>'source_url')+regexp_count(v->>'source_url','[\U00010000-\U0010FFFF]')
          <=(c->'basis'->'source_url'->>'max_length')::integer
        and (v->>'source_url') ~ (c->'basis'->'source_url'->>'pattern'),false) then return false; end if;
    if (coalesce(jsonb_typeof(v->'effective_date'),'null')<>'null' and not public.contract_date(v->'effective_date'))
      or (coalesce(jsonb_typeof(v->'expires_on'),'null')<>'null' and not public.contract_date(v->'expires_on'))
    then return false; end if;
    if jsonb_typeof(v->'effective_date')='string' and jsonb_typeof(v->'expires_on')='string'
      and (v->>'expires_on') collate "C"<=(v->>'effective_date') collate "C" then return false; end if;
  end if;
  return true;
end;
$$;

-- The legacy space_type a condition is stored under (§1.3): the first
-- to_space_type rule that matches, or null.
create or replace function public.condition_space_type(p_condition jsonb,p_off_street boolean) returns text
language plpgsql immutable set search_path='' as $$
declare p jsonb:=p_condition; r jsonb; w jsonb;
begin
  for r in select e from jsonb_array_elements(public.parking_contract()->'conversion'->'to_space_type') e loop
    w:=r->'when';
    if (not w ? 'placement' or p_off_street)
      and (not w ? 'limit' or exists(select 1 from jsonb_array_elements(
        case when jsonb_typeof(p->'limits')='array' then p->'limits' else '[]'::jsonb end) l
        where l->>'kind'=w->>'limit'))
      and (not w ? 'share' or p->>'share' is not distinct from w->>'share')
      and (not w ? 'bay' or p->>'bay' is not distinct from w->>'bay')
      and (not w ? 'charge' or p->>'charge' is not distinct from w->>'charge')
    then return r->>'space_type'; end if;
  end loop;
  return null;
end;
$$;

-- Whether a spot is off the street (§1.1 placement); never stored.
create or replace function public.condition_off_street(p_space_type text,p_facility_type text) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(public.parking_contract()->'placement'->'off_street_space_types' ? p_space_type,false)
    or coalesce(public.parking_contract()->'placement'->'off_street_facility_types' ? p_facility_type,false);
$$;

-- The legacy access a zone condition is written back as (§1.3, to_access):
-- the from_access entry with the same allow and, when the entry names a bay,
-- the same bay; null when none matches. At most one entry can match.
create or replace function public.condition_legacy_access(p_condition jsonb) returns text
language sql immutable set search_path='' as $$
  select min(a.key) from jsonb_each(public.parking_contract()->'conversion'->'from_access') a
  where jsonb_typeof(p_condition->'allow')='object'
    and (a.value->'allow'->'scooter') is not distinct from (p_condition->'allow'->'scooter')
    and (a.value->'allow'->'heavy') is not distinct from (p_condition->'allow'->'heavy')
    and (not a.value ? 'bay' or (a.value->'bay') is not distinct from (p_condition->'bay'));
$$;

-- legacySafe (§1.3, conversion.legacy_safe): whether old apps, reading only
-- the legacy space_type (a street condition) or access (p_zone), see the
-- same condition or a more conservative one. Converts and reads back, then
-- compares, losing only (a) scooter_heavy read back as usual, (b) a basis
-- without the unsafe keys, (c) the lossy limit keys and (d) facets the read
-- back leaves unconfirmed, except a charge old apps assume. Null is safe.
create or replace function public.condition_legacy_safe(p_condition jsonb,p_zone boolean default false) returns boolean
language plpgsql immutable set search_path='' as $$
declare
  conv jsonb:=public.parking_contract()->'conversion';
  r jsonb:=conv->'legacy_safe';
  o jsonb:=p_condition; b jsonb; t text; k text;
  lossy text[]:=array(select jsonb_array_elements_text(r->'lossy_limit_keys'));
begin
  if o is null or jsonb_typeof(o)='null' then return true; end if;
  if p_zone then
    t:=public.condition_legacy_access(o);
    b:=conv->'from_access'->t;
  else
    t:=public.condition_space_type(o,false);
    b:=conv->'from_space_type'->t;
  end if;
  if b is null or jsonb_typeof(b)<>'object' then return false; end if;
  if o ?| array(select jsonb_array_elements_text(r->'unsafe_keys')) then return false; end if;
  -- (b) a basis without the unsafe keys; a null value counts as left out.
  if exists(select 1 from jsonb_array_elements_text(r->'unsafe_basis_keys') x
      where coalesce(jsonb_typeof(o->'basis'->x),'null')<>'null') then return false; end if;
  o:=o-'basis'; b:=b-'basis';
  -- (c) limit keys old apps never read.
  if jsonb_typeof(o->'limits')='array' then
    o:=jsonb_set(o,'{limits}',(select jsonb_agg(e-lossy) from jsonb_array_elements(o->'limits') e));
  end if;
  if jsonb_typeof(b->'limits')='array' then
    b:=jsonb_set(b,'{limits}',(select jsonb_agg(e-lossy) from jsonb_array_elements(b->'limits') e));
  end if;
  -- (a) a shared use read back as usual.
  if o->>'share'=r->>'lossy_share' and b->>'use'='usual' and not b ? 'share' then
    o:=(o-'share')||'{"use":"usual"}'::jsonb;
  end if;
  -- (d) facets the legacy value leaves unconfirmed, except an assumed charge.
  if not p_zone and r->'assumed_charge' ? t and not b ? 'charge' and o ? 'charge'
    and o->>'charge'<>r->'assumed_charge'->>t then return false; end if;
  for k in select jsonb_array_elements_text(r->'lossy_when_unconfirmed') loop
    if not b ? k then o:=o-k; end if;
  end loop;
  return o=b;
end;
$$;

-- Whether old builds, which read a zone's access only, read a stored zone
-- (an element of parking_zones) as it is: it has no condition, or a
-- legacy-safe one stored with the access it writes back.
create or replace function public.zone_legacy_safe(p_zone jsonb) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(jsonb_typeof(p_zone->'condition'),'null')='null'
    or (public.condition_legacy_safe(p_zone->'condition',true)
      and (p_zone->>'access') is not distinct from public.condition_legacy_access(p_zone->'condition'));
$$;

-- Whether a zone's access agrees with its condition (§1.3, decision 32): a
-- zone without a condition is not checked here; one with a condition has an
-- allow naming both vehicles, and its access is the one the condition writes
-- back. A condition that writes back no access is inconsistent, except one
-- whose allow says not_stated for a vehicle (#201): it has no access to
-- write back, so the zone carries none.
create or replace function public.zone_condition_consistent(p_zone jsonb) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(jsonb_typeof(p_zone->'condition'),'null')='null'
    or case when jsonb_typeof(p_zone->'condition'->'allow')='object' and exists(
        select 1 from jsonb_each(p_zone->'condition'->'allow') e
        where e.value=(public.parking_contract()->'eligibility'->'not_stated'))
      then coalesce(jsonb_typeof(p_zone->'access'),'null')='null'
        and p_zone->'condition'->'allow' ?& array['scooter','heavy']
      else jsonb_typeof(p_zone->'access')='string'
        and coalesce((p_zone->>'access')=public.condition_legacy_access(p_zone->'condition'),false) end;
$$;

-- Whether a whole spot is legacy-safe: a street spot by its condition, a lot
-- only without a top-level condition and when every zone is.
create or replace function public.condition_legacy_safe_spot(p_off_street boolean,p_condition jsonb,p_zones jsonb) returns boolean
language sql immutable set search_path='' as $$
  select case when p_off_street then coalesce(jsonb_typeof(p_condition),'null')='null'
      and not exists(select 1 from jsonb_array_elements(
        case when jsonb_typeof(p_zones)='array' then p_zones else '[]'::jsonb end) z
        where not public.zone_legacy_safe(z))
    else public.condition_legacy_safe(p_condition,false) end;
$$;

-- ===== 費率 v2：valid_fee(p_fee)（只屬於 C3；C2 不可複製，否則會提早換掉現行的費率檢查） =====

-- The keys of p (besides mode) against a {required, optional} spec: ranges
-- (max may name a sibling key), enums and periods.
create or replace function public.contract_fee_fields(p jsonb,p_spec jsonb,p_vehicle text) returns boolean
language plpgsql immutable set search_path='' as $$
declare fee jsonb:=public.parking_contract()->'fee'; f record; fs jsonb; hi numeric;
begin
  if jsonb_typeof(p) is distinct from 'object' then return false; end if;
  for f in select key,value from jsonb_each(p) loop
    continue when f.key='mode';
    fs:=coalesce(p_spec->'required'->f.key,p_spec->'optional'->f.key);
    if fs is null then return false; end if;
    if jsonb_typeof(fs)='object' then
      if jsonb_typeof(fs->'max')='string' then
        hi:=case when public.contract_whole(p->(fs->>'max'),0,1e9) then (p->>(fs->>'max'))::numeric end;
        if hi is null then return false; end if;
      else hi:=(fs->>'max')::numeric; end if;
      if not public.contract_whole(f.value,(fs->>'min')::numeric,hi) then return false; end if;
    elsif fee->'enums' ? (fs#>>'{}') then
      if not public.contract_str_in(f.value,fee->'enums'->(fs#>>'{}')) then return false; end if;
    elsif fs#>>'{}'='periods' then
      if jsonb_typeof(f.value) is distinct from 'array'
        or jsonb_array_length(f.value) not between 1 and (fee->'periods'->>'max_entries')::integer
        or exists(select 1 from jsonb_array_elements(f.value) e
          where not public.contract_slot_keys(e,fee->'periods'->'keys') or not public.contract_slot_times(e)
            or not public.contract_fee_rate(e->'rate',p_vehicle,true))
      then return false; end if;
    else return false; end if;
  end loop;
  return not exists(select 1 from jsonb_object_keys(p_spec->'required') r where not p ? r);
end;
$$;

-- One vehicle's rate (§2.2); a period's rate may not follow or nest by_time.
create or replace function public.contract_fee_rate(p jsonb,p_vehicle text,p_nested boolean) returns boolean
language plpgsql immutable set search_path='' as $$
declare fee jsonb:=public.parking_contract()->'fee'; m text;
begin
  if jsonb_typeof(p) is distinct from 'object' or jsonb_typeof(p->'mode') is distinct from 'string' then return false; end if;
  m:=p->>'mode';
  if fee->'follow'->'modes' ? m then
    return not p_nested and fee->'follow'->'vehicles' ? p_vehicle
      and public.contract_fee_fields(p,jsonb_build_object('required','{}'::jsonb,'optional',fee->'follow'->'optional'),p_vehicle);
  end if;
  if not fee->'modes' ? m or (p_nested and not fee->'periods'->'nested_modes' ? m) then return false; end if;
  return public.contract_fee_fields(p,fee->'modes'->m,p_vehicle);
end;
$$;

-- Fee v2 (§2.2): a rate per vehicle; a missing vehicle is unconfirmed.
create or replace function public.valid_fee(p_fee jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare fee jsonb:=public.parking_contract()->'fee'; p jsonb:=p_fee;
begin
  if jsonb_typeof(p) is distinct from 'object' then return false; end if;
  return pg_column_size(p)<=(fee->>'max_bytes')::integer
    and not exists(select 1 from jsonb_object_keys(p) k where not fee->'vehicles' ? k)
    and not exists(select 1 from jsonb_object_keys(p) k where not public.contract_fee_rate(p->k,k,false));
end;
$$;

-- ===== 費率文字：fee_note_of(p_fee)（C3；與 tool/fee_text.py、lib/models/fee.dart、
-- supabase/functions/_shared/fee.ts 同一套句子，parking_contract_cases.json 的 fee_notes 固定） =====

-- Whole yuan times a factor in percent, with at most two decimals: 22.5, 41.25.
create or replace function public.fee_text_money(p jsonb,p_pct integer) returns text
language sql immutable set search_path='' as $$
  select case when v%100=0 then (v/100)::text
    when v%10=0 then (v/100)::text||'.'||(v%100/10)::text
    else (v/100)::text||'.'||lpad((v%100)::text,2,'0') end
  from (select (p#>>'{}')::numeric::bigint*p_pct as v) x;
$$;

-- 3 小時, 45 分鐘.
create or replace function public.fee_text_span(p jsonb) returns text
language sql immutable set search_path='' as $$
  select case when m%60=0 then (m/60)||' 小時' else m||' 分鐘' end
  from (select (p#>>'{}')::numeric::integer as m) x;
$$;

-- 每小時, 每 2 小時, 每 90 分鐘.
create or replace function public.fee_text_every(p jsonb) returns text
language sql immutable set search_path='' as $$
  select case when m=60 then '每小時' when m%60=0 then '每 '||(m/60)||' 小時' else '每 '||m||' 分鐘' end
  from (select (p#>>'{}')::numeric::integer as m) x;
$$;

-- When a cap or a daily charge starts over; null when unconfirmed.
create or replace function public.fee_text_reset(p text) returns text
language sql immutable set search_path='' as $$
  select case p when 'calendar_day' then '零時重算' when 'rolling_24h' then '停滿 24 小時重算'
    when 'per_entry' then '每次進場重算' end;
$$;

-- A set of days as a bit mask (bit 0 Monday) and its label.
create or replace function public.fee_text_day_mask(p jsonb) returns integer
language sql immutable set search_path='' as $$
  select case when jsonb_typeof(p)='string' then case p#>>'{}' when 'all' then 127 when 'weekday' then 31 else 96 end
    else (select sum(1<<(array_position(array['mon','tue','wed','thu','fri','sat','sun'],d)-1))::integer
      from jsonb_array_elements_text(p) d) end;
$$;

create or replace function public.fee_text_days(p_mask integer) returns text
language sql immutable set search_path='' as $$
  select case p_mask when 127 then '每天' when 31 then '平日' when 96 then '假日'
    else (select string_agg('週'||substr('一二三四五六日',i+1,1),'、' order by i)
      from generate_series(0,6) i where p_mask&(1<<i)<>0) end;
$$;

-- One rate's words at p_pct percent of its amounts, or null when it reads
-- as unconfirmed or does not apply (not_applicable, a follow).
create or replace function public.fee_text_rate(p jsonb,p_pct integer) returns text
language plpgsql immutable set search_path='' as $$
declare
  m text:=p->>'mode'; t text; e jsonb; mask integer; i integer;
  masks integer[]:='{}'; parts text[]:='{}';
begin
  if jsonb_typeof(p) is distinct from 'object' then return null; end if;
  if m='free' then return '免費'; end if;
  if m='hourly' then
    t:=public.fee_text_every(p->'per_minutes')||' '||public.fee_text_money(p->'amount',p_pct)||' 元';
    if p ? 'daily_cap' then
      t:=t||'，當日上限 '||public.fee_text_money(p->'daily_cap',p_pct)||' 元'
        ||coalesce('（'||public.fee_text_reset(p->>'cap_reset')||'）','');
    end if;
    return t;
  end if;
  if m='per_visit' then
    return '每次 '||public.fee_text_money(p->'amount',p_pct)||' 元'
      ||case p->>'renew' when 'midnight' then '，隔日另計' when 'none' then '，停多久都只收一次'
        else '' end
      ||case when p ? 'extension_amount' then '，延長每次 '||public.fee_text_money(p->'extension_amount',p_pct)||' 元' else '' end;
  end if;
  if m='by_time' then
    -- Periods grouped by the days they cover, in order of first appearance.
    for e in select x from jsonb_array_elements(p->'periods') x loop
      t:=public.fee_text_rate(e->'rate',p_pct);
      continue when t is null;
      t:=case when e ? 'from' then (e->>'from')||'–'
          ||case when (e->>'from') collate "C"<(e->>'to') collate "C" then '' else '隔日 ' end||(e->>'to')
        else '全天' end||' '||t;
      mask:=public.fee_text_day_mask(e->'days');
      i:=array_position(masks,mask);
      if i is null then masks:=masks||mask; parts:=parts||t; else parts[i]:=parts[i]||'；'||t; end if;
    end loop;
    if cardinality(masks)=0 then return null; end if;
    t:=(select string_agg(public.fee_text_days(masks[k])||'：'||parts[k],'；' order by k)
      from generate_subscripts(masks,1) k);
    if p ? 'cross_period' then
      t:=t||'；'||case p->>'cross_period' when 'each_period' then '跨時段分別計費' else '依進場時段計費' end;
    end if;
    return t;
  end if;
  return null;
end;
$$;

-- The fee_note text of a valid fee: known vehicles as 機車…；大型重機…；汽車…,
-- then 大型重機費率未提供 when the heavy rate is unknown (PM_ANS_20261101_55;
-- old rates missing renew, cap_reset or cross_period say nothing of them); a vehicle that is
-- not_applicable (#188) is left out. A heavy rate that follows another
-- vehicle shows that vehicle's amounts (#140; no factor since #188), or
-- 大型重機費率未提供 when that vehicle is unconfirmed or not applicable.
create or replace function public.fee_note_of(p_fee jsonb) returns text
language plpgsql immutable set search_path='' as $$
declare
  f text:=p_fee->'heavy'->>'mode'; s text; h text; c text; unprovided boolean:=false; parts text[]:='{}';
begin
  s:=public.fee_text_rate(p_fee->'scooter',100);
  c:=public.fee_text_rate(p_fee->'car',100);
  if f in ('same_as_scooter','same_as_car') then
    h:=public.fee_text_rate(p_fee->(case f when 'same_as_scooter' then 'scooter' else 'car' end),100);
    unprovided:=h is null;
  else
    h:=public.fee_text_rate(p_fee->'heavy',100);
  end if;
  if s is null and h is null and c is null and not unprovided then return '請依現場公告'; end if;
  if s is not null then parts:=parts||('機車'||s); end if;
  if h is not null or unprovided then parts:=parts||('大型重機'||coalesce(h,'費率未提供')); end if;
  if c is not null then parts:=parts||('汽車'||c); end if;
  if h is null and not unprovided and f is distinct from 'not_applicable' then
    parts:=parts||'大型重機費率未提供'::text;
  end if;
  return array_to_string(parts,'；');
end;
$$;

-- Whether one rate is complete for a new write (#188 layer 2, fee.write):
-- a per-visit rate names renew, an hourly cap names its cap_reset, and a
-- by_time rate names cross_period once it has min_periods periods with a
-- nested_mode one; its periods' rates follow the same rules. p is valid.
create or replace function public.fee_rate_write_complete(p jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare w jsonb:=public.parking_contract()->'fee'->'write'; m text:=p->>'mode'; r record;
begin
  if jsonb_typeof(p) is distinct from 'object' then return false; end if;
  if exists(select 1 from jsonb_array_elements_text(coalesce(w->'required'->m,'[]'::jsonb)) k where not p ? k) then
    return false;
  end if;
  for r in select key,value from jsonb_each_text(coalesce(w->'required_with'->m,'{}'::jsonb)) loop
    if p ? r.value and not p ? r.key then return false; end if;
  end loop;
  if m='by_time' then
    if exists(select 1 from jsonb_array_elements(p->'periods') e where not public.fee_rate_write_complete(e->'rate')) then
      return false;
    end if;
    if not p ? 'cross_period' and jsonb_array_length(p->'periods')>=(w->'cross_period_when'->>'min_periods')::integer
      and exists(select 1 from jsonb_array_elements(p->'periods') e
        where e->'rate'->>'mode'=w->'cross_period_when'->>'nested_mode') then return false; end if;
  end if;
  return true;
end;
$$;

-- Whether a whole fee is complete for a new write (fee.write): every
-- required vehicle has a rate, and each rate is complete. p_fee is valid.
create or replace function public.fee_write_complete(p_fee jsonb) returns boolean
language sql immutable set search_path='' as $$
  select jsonb_typeof(p_fee)='object'
    and p_fee ?& array(select jsonb_array_elements_text(public.parking_contract()->'fee'->'write'->'required_vehicles'))
    and not exists(select 1 from jsonb_each(p_fee) e where not public.fee_rate_write_complete(e.value));
$$;

-- ===== 計費規則：valid_fee_plans()（C3 第二層，§2.6） =====

-- A spot's fee plans, its own plan reference and its zones' (§2.6): at
-- most max_entries plans of {id, name, fee}, ids unique and of id_pattern,
-- names of 1–name_max_length UTF-16 code units, each fee a valid, non-empty
-- fee. Every reference names an existing plan, and a spot or zone that
-- refers to one carries that plan's fee as its own copy for older builds.
create or replace function public.valid_fee_plans(p_plans jsonb,p_fee_plan text,p_fee jsonb,p_zones jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare c jsonb:=public.parking_contract()->'fee_plans'; p jsonb; z jsonb; ids text[]:='{}';
begin
  if coalesce(jsonb_typeof(p_plans),'null')<>'null' then
    if jsonb_typeof(p_plans)<>'array'
      or jsonb_array_length(p_plans) not between 1 and (c->>'max_entries')::integer then return false; end if;
    for p in select e from jsonb_array_elements(p_plans) e loop
      if jsonb_typeof(p) is distinct from 'object'
        or exists(select 1 from jsonb_object_keys(p) k where not c->'keys' ? k)
        or exists(select 1 from jsonb_array_elements_text(c->'keys') k where not p ? k)
        or jsonb_typeof(p->'id') is distinct from 'string' or (p->>'id') !~ (c->>'id_pattern') or (p->>'id')=any(ids)
        or jsonb_typeof(p->'name') is distinct from 'string' or btrim(p->>'name')=''
        -- UTF-16 code units, as Dart and JS count.
        or char_length(p->>'name')+regexp_count(p->>'name','[\U00010000-\U0010FFFF]')>(c->>'name_max_length')::integer
        or not public.valid_fee(p->'fee') or p->'fee'='{}'::jsonb then return false; end if;
      ids:=ids||(p->>'id');
    end loop;
  end if;
  if p_fee_plan is not null and (not p_fee_plan=any(ids) or p_fee is distinct from
      (select e->'fee' from jsonb_array_elements(p_plans) e where e->>'id'=p_fee_plan)) then return false; end if;
  for z in select e from jsonb_array_elements(case when jsonb_typeof(p_zones)='array' then p_zones else '[]'::jsonb end) e loop
    continue when jsonb_typeof(z) is distinct from 'object' or not z ? 'fee_plan';
    if jsonb_typeof(z->'fee_plan') is distinct from 'string' or not (z->>'fee_plan')=any(ids)
      or (z->'fee') is distinct from (select e->'fee' from jsonb_array_elements(p_plans) e where e->>'id'=z->>'fee_plan')
    then return false; end if;
  end loop;
  return true;
end;
$$;

-- A street spot's segments that refer to a fee plan (#188 layer 2): each
-- reference names one of p_plans and the segment carries that plan's fee,
-- as valid_fee_plans() holds zones to it.
create or replace function public.valid_segment_fee_plans(p_plans jsonb,p_segments jsonb) returns boolean
language sql immutable set search_path='' as $$
  select not exists(select 1 from jsonb_array_elements(
      case when jsonb_typeof(p_segments)='array' then p_segments else '[]'::jsonb end) g
    where jsonb_typeof(g)='object' and g ? 'fee_plan'
      and (jsonb_typeof(g->'fee_plan') is distinct from 'string'
        or not exists(select 1 from jsonb_array_elements(
            case when jsonb_typeof(p_plans)='array' then p_plans else '[]'::jsonb end) e
          where e->>'id'=g->>'fee_plan' and e->'fee'=g->'fee')));
$$;

-- The longest fee_note_of() the contract allows (§2.5), worked out by
-- tool/fee_text.py: the bound of both spot tables' fee_note check and of
-- validate.ts for a note that is its fee's text.
create or replace function public.fee_note_max_length() returns integer
language sql immutable set search_path='' as $$
  select 1399;
$$;

-- ===== 分區與路段：valid_zones()、valid_segments()、condition_bay_kind()（#188） =====

-- An https link of at most max_length UTF-16 code units: the rule of a
-- basis source_url, used by a zone's or a segment's evidence_url.
create or replace function public.contract_https(p jsonb) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(jsonb_typeof(p)='string'
    and char_length(p#>>'{}')+regexp_count(p#>>'{}','[\U00010000-\U0010FFFF]')
      <=(public.parking_contract()->'condition'->'basis'->'source_url'->>'max_length')::integer
    and (p#>>'{}') ~ (public.parking_contract()->'condition'->'basis'->'source_url'->>'pattern'),false);
$$;

-- A string of at most p_max UTF-16 code units that is not blank.
create or replace function public.contract_text(p jsonb,p_max integer) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(jsonb_typeof(p)='string' and btrim(p#>>'{}')<>''
    and char_length(p#>>'{}')+regexp_count(p#>>'{}','[\U00010000-\U0010FFFF]')<=p_max,false);
$$;

-- The ids of a zone or segment list (an array): each id that is present is
-- a string of zone.id_pattern, and no two entries share one. Entries may
-- leave it out; the tables' trigger fills it in before their checks.
create or replace function public.contract_entry_ids(p jsonb) returns boolean
language sql immutable set search_path='' as $$
  select not exists(select 1 from jsonb_array_elements(p) e
      where jsonb_typeof(e)='object' and e ? 'id' and (jsonb_typeof(e->'id') is distinct from 'string'
        or (e->>'id') !~ (public.parking_contract()->'zone'->>'id_pattern')))
    and (select count(e->>'id') from jsonb_array_elements(p) e where jsonb_typeof(e)='object')
      =(select count(distinct e->>'id') from jsonb_array_elements(p) e where jsonb_typeof(e)='object');
$$;

-- A spot's parking_zones (§1.1, decision 32, #188): objects with a valid
-- fee and condition (whose access agrees with it), an optional https
-- evidence_url, and ids as contract_entry_ids() takes them. area is gone
-- (#188 layer 2): the tables' trigger drops it before this check.
create or replace function public.valid_zones(p_zones jsonb) returns boolean
language sql immutable set search_path='' as $$
  select case when jsonb_typeof(p_zones) is distinct from 'array' then false else
    not exists(select 1 from jsonb_array_elements(p_zones) z
      where jsonb_typeof(z) is distinct from 'object'
        or (z ? 'fee' and not public.valid_fee(z->'fee'))
        or (z ? 'condition' and not (public.valid_condition(z->'condition',true)
          and public.zone_condition_consistent(z)))
        or (z ? 'evidence_url' and not public.contract_https(z->'evidence_url')))
    and public.contract_entry_ids(p_zones) end;
$$;

-- A street spot's parking_segments (#188, segment): at most max_entries
-- objects of the listed keys, each named, with an optional side, range,
-- guide, number of bays, https evidence_url, a zone-style condition (its
-- allow says who may park there, layer 2) and its own fee and fee_plan
-- reference (valid_segment_fee_plans() checks the reference).
create or replace function public.valid_segments(p_segments jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare c jsonb:=public.parking_contract()->'segment'; s jsonb;
begin
  if jsonb_typeof(p_segments) is distinct from 'array'
    or jsonb_array_length(p_segments)>(c->>'max_entries')::integer then return false; end if;
  for s in select e from jsonb_array_elements(p_segments) e loop
    if jsonb_typeof(s) is distinct from 'object'
      or exists(select 1 from jsonb_object_keys(s) k where not c->'keys' ? k)
      or not public.contract_text(s->'name',(c->>'name_max_length')::integer)
      or (s ? 'side' and not public.contract_str_in(s->'side',c->'sides'))
      or (s ? 'range' and not public.contract_text(s->'range',(c->>'range_max_length')::integer))
      or (s ? 'guide' and not public.contract_text(s->'guide',(c->>'guide_max_length')::integer))
      or (s ? 'total' and not public.contract_whole(s->'total',(c->'total'->>'min')::numeric,(c->'total'->>'max')::numeric))
      or (s ? 'condition' and not public.valid_condition(s->'condition',true))
      or (s ? 'fee' and not public.valid_fee(s->'fee'))
      or (s ? 'fee_plan' and jsonb_typeof(s->'fee_plan') is distinct from 'string')
      or (s ? 'evidence_url' and not public.contract_https(s->'evidence_url'))
    then return false; end if;
  end loop;
  return public.contract_entry_ids(p_segments);
end;
$$;

-- Whether a condition is complete for a new write (#188 layer 2,
-- condition.write): each limit kind listed in limits_required carries its
-- keys (time_limit its periods, not the old shapes). p_condition is valid.
create or replace function public.condition_write_complete(p_condition jsonb) returns boolean
language sql immutable set search_path='' as $$
  select jsonb_typeof(p_condition)='object' and not exists(select 1 from jsonb_array_elements(
      case when jsonb_typeof(p_condition->'limits')='array' then p_condition->'limits' else '[]'::jsonb end) l
    cross join lateral jsonb_array_elements_text(coalesce(
      public.parking_contract()->'condition'->'write'->'limits_required'->(l->>'kind'),'[]'::jsonb)) k
    where not l ? k);
$$;

-- The bay kind a condition reads as (#188, bay_kinds): the first rule that
-- matches, or null (unconfirmed).
create or replace function public.condition_bay_kind(p_condition jsonb) returns text
language plpgsql immutable set search_path='' as $$
declare r jsonb; w jsonb;
begin
  if jsonb_typeof(p_condition) is distinct from 'object' then return null; end if;
  for r in select e from jsonb_array_elements(public.parking_contract()->'bay_kinds'->'rules') e loop
    w:=r->'when';
    if (not w ? 'limit' or exists(select 1 from jsonb_array_elements(
        case when jsonb_typeof(p_condition->'limits')='array' then p_condition->'limits' else '[]'::jsonb end) l
        where l->>'kind'=w->>'limit'))
      and (not w ? 'share' or p_condition->>'share' is not distinct from w->>'share')
      and (not w ? 'bay' or p_condition->>'bay' is not distinct from w->>'bay')
    then return r->>'bay_kind'; end if;
  end loop;
  return null;
end;
$$;

-- ===== 費率舊形狀轉換（步驟 4） =====

-- One rate in the layer-2 shape (#188): daily becomes per_visit (renew
-- from its cap_reset: calendar_day or none → midnight, per_entry → none,
-- rolling_24h → left out), posted and an emptied by_time become null (the
-- vehicle is left out), hourly loses free_minutes and unit_minutes,
-- per_visit loses max_minutes and takes its extension's amount as
-- extension_amount, a follow loses factor_pct, and a by_time's periods are
-- upgraded (a posted period goes). Anything else is returned as it is.
create function public.fee_rate_upgrade(p jsonb) returns jsonb
language plpgsql immutable set search_path='' as $$
declare m text:=p->>'mode'; v jsonb; e jsonb; r jsonb; ps jsonb:='[]'::jsonb;
begin
  if jsonb_typeof(p) is distinct from 'object' then return p; end if;
  if m='posted' then return null; end if;
  if m='daily' then
    v:=jsonb_build_object('mode','per_visit','amount',p->'amount');
    if coalesce(p->>'cap_reset','calendar_day')='calendar_day' then v:=v||'{"renew":"midnight"}';
    elsif p->>'cap_reset'='per_entry' then v:=v||'{"renew":"none"}'; end if;
    return v;
  end if;
  if m='hourly' then return p-'free_minutes'-'unit_minutes'; end if;
  if m='per_visit' then
    v:=p-'max_minutes'-'extension';
    if jsonb_typeof(p->'extension')='object' and p->'extension' ? 'amount' then
      v:=v||jsonb_build_object('extension_amount',p->'extension'->'amount');
    end if;
    return v;
  end if;
  if m in ('same_as_scooter','same_as_car') then return p-'factor_pct'; end if;
  if m='by_time' and jsonb_typeof(p->'periods')='array' then
    for e in select x from jsonb_array_elements(p->'periods') with ordinality t(x,n) order by n loop
      r:=public.fee_rate_upgrade(e->'rate');
      if r is not null then ps:=ps||jsonb_build_array(jsonb_set(e,'{rate}',r)); end if;
    end loop;
    if jsonb_array_length(ps)=0 then return null; end if;
    return jsonb_set(p,'{periods}',ps);
  end if;
  return p;
end;
$$;

-- A fee in the layer-2 shape: each vehicle's rate upgraded, a vehicle whose
-- rate became null left out. A heavy follow with a factor other than 100
-- becomes the followed rate itself (no factor since #188; none on staging):
-- whole amounts rounded up. Null and non-objects stay as they are.
create function public.fee_upgrade(p_fee jsonb) returns jsonb
language plpgsql immutable set search_path='' as $$
declare v jsonb:='{}'::jsonb; k text; r jsonb; t jsonb; pct numeric;
begin
  if jsonb_typeof(p_fee) is distinct from 'object' then return p_fee; end if;
  for k,r in select key,value from jsonb_each(p_fee) loop
    if k='heavy' and r->>'mode' in ('same_as_scooter','same_as_car') and coalesce((r->>'factor_pct')::numeric,100)<>100 then
      pct:=(r->>'factor_pct')::numeric;
      t:=public.fee_rate_upgrade(p_fee->(case r->>'mode' when 'same_as_scooter' then 'scooter' else 'car' end));
      r:=case when jsonb_typeof(t)='object' and t ? 'amount' and t->>'mode'<>'by_time' then
          t||jsonb_build_object('amount',ceil((t->>'amount')::numeric*pct/100))
           ||case when t ? 'daily_cap' then jsonb_build_object('daily_cap',ceil((t->>'daily_cap')::numeric*pct/100)) else '{}' end
           ||case when t ? 'extension_amount' then jsonb_build_object('extension_amount',ceil((t->>'extension_amount')::numeric*pct/100)) else '{}' end
        end;
    else
      r:=public.fee_rate_upgrade(r);
    end if;
    if r is not null then v:=v||jsonb_build_object(k,r); end if;
  end loop;
  return v;
end;
$$;

-- The ids of the plans in p whose fee upgrades to nothing (a plan of
-- posted rates only): they go, with every reference to them.
create function public.fee_plans_emptied(p jsonb) returns text[]
language sql immutable set search_path='' as $$
  select coalesce(array(select e->>'id' from jsonb_array_elements(
      case when jsonb_typeof(p)='array' then p else '[]'::jsonb end) e
    where jsonb_typeof(e)='object' and public.fee_upgrade(e->'fee')='{}'::jsonb),'{}');
$$;

-- Each entry of a zone or segment list with its fee upgraded and its area
-- dropped; a reference to a plan of p_emptied goes (the entry keeps its
-- upgraded copy of the fee); null when p is null.
create function public.entries_upgrade(p jsonb,p_emptied text[] default '{}') returns jsonb
language sql immutable set search_path='' as $$
  select case when jsonb_typeof(p)='array' then coalesce((select jsonb_agg(
      case when jsonb_typeof(z)<>'object' then z
        else (case when z ? 'fee' then jsonb_set(z-'area','{fee}',coalesce(public.fee_upgrade(z->'fee'),'{}'::jsonb))
            else z-'area' end)
          -case when (z->>'fee_plan')=any(p_emptied) then 'fee_plan' else '' end end order by n)
      from jsonb_array_elements(p) with ordinality x(z,n)),'[]'::jsonb)
    else p end;
$$;

-- A spot's fee plans with every plan's fee upgraded, those left empty
-- dropped; null when none is left or p is null.
create function public.fee_plans_upgrade(p jsonb) returns jsonb
language sql immutable set search_path='' as $$
  select case when jsonb_typeof(p)='array' then (select jsonb_agg(
      case when jsonb_typeof(e)='object' then jsonb_set(e,'{fee}',public.fee_upgrade(e->'fee')) else e end
      order by n) from jsonb_array_elements(p) with ordinality x(e,n)
      where not (jsonb_typeof(e)='object' and public.fee_upgrade(e->'fee')='{}'::jsonb))
    else p end;
$$;

do $$
declare r record;
begin
  for r in
    select 'community' t,id,fee from public.community_spots
      where (coalesce(fee::text,'')||coalesce(fee_plans::text,'')||parking_zones::text) ~ '"max_minutes"'
    union all
    select 'official',id,fee from public.official_heavy_spots
      where (coalesce(fee::text,'')||coalesce(fee_plans::text,'')||parking_zones::text) ~ '"max_minutes"'
  loop
    raise notice '#188 layer 2: % spot % drops a per-visit max_minutes (review it as a time limit): %',r.t,r.id,r.fee;
  end loop;
end;
$$;

-- Plain updates: updated_at, the data version and the history stay; the
-- fee plans stay copies of each other because every fee is upgraded alike.
-- A note that was the old sentence of its fee is rewritten in the same
-- update, so the fee_note check (a long note is its fee's sentence) holds
-- row by row. A plan left empty goes with its references.
alter table public.community_spots disable trigger user;
alter table public.official_heavy_spots disable trigger user;
update public.community_spots c set
    fee=public.fee_upgrade(c.fee),
    fee_note=case when exists(select 1 from t188_generated_notes g where g.t='community' and g.id=c.id)
      then public.fee_note_of(public.fee_upgrade(c.fee)) else c.fee_note end,
    fee_plans=public.fee_plans_upgrade(c.fee_plans),
    fee_plan=case when c.fee_plan=any(public.fee_plans_emptied(c.fee_plans)) then null else c.fee_plan end,
    parking_zones=public.entries_upgrade(c.parking_zones,public.fee_plans_emptied(c.fee_plans)),
    parking_segments=public.entries_upgrade(c.parking_segments,public.fee_plans_emptied(c.fee_plans))
  where c.fee is distinct from public.fee_upgrade(c.fee) or c.fee_plans is distinct from public.fee_plans_upgrade(c.fee_plans)
    or c.parking_zones is distinct from public.entries_upgrade(c.parking_zones)
    or c.parking_segments is distinct from public.entries_upgrade(c.parking_segments)
    -- A fee whose shape stays but whose sentence changes (#188 layer 2).
    or (exists(select 1 from t188_generated_notes g where g.t='community' and g.id=c.id)
      and c.fee_note is distinct from public.fee_note_of(public.fee_upgrade(c.fee)));
update public.official_heavy_spots o set
    fee=public.fee_upgrade(o.fee),
    fee_note=case when exists(select 1 from t188_generated_notes g where g.t='official' and g.id=o.id)
      then public.fee_note_of(public.fee_upgrade(o.fee)) else o.fee_note end,
    fee_plans=public.fee_plans_upgrade(o.fee_plans),
    fee_plan=case when o.fee_plan=any(public.fee_plans_emptied(o.fee_plans)) then null else o.fee_plan end,
    parking_zones=public.entries_upgrade(o.parking_zones,public.fee_plans_emptied(o.fee_plans)),
    parking_segments=public.entries_upgrade(o.parking_segments,public.fee_plans_emptied(o.fee_plans))
  where o.fee is distinct from public.fee_upgrade(o.fee) or o.fee_plans is distinct from public.fee_plans_upgrade(o.fee_plans)
    or o.parking_zones is distinct from public.entries_upgrade(o.parking_zones)
    or o.parking_segments is distinct from public.entries_upgrade(o.parking_segments)
    -- A fee whose shape stays but whose sentence changes (#188 layer 2).
    or (exists(select 1 from t188_generated_notes g where g.t='official' and g.id=o.id)
      and o.fee_note is distinct from public.fee_note_of(public.fee_upgrade(o.fee)));
alter table public.community_spots enable trigger user;
alter table public.official_heavy_spots enable trigger user;
drop table t188_generated_notes;

-- Pending suggestions apply on today's tables: their fees (merged per
-- vehicle, so a posted one becomes a vehicle left alone) and zone patches.
update public.moderation_queue set proposed=proposed
    ||case when jsonb_typeof(proposed->'fee')='object' then jsonb_build_object('fee',(
        select coalesce(jsonb_object_agg(k,case when x='null'::jsonb then x else public.fee_rate_upgrade(x) end),'{}'::jsonb)
        from jsonb_each(proposed->'fee') j(k,x) where x='null'::jsonb or public.fee_rate_upgrade(x) is not null)) else '{}' end
    ||case when jsonb_typeof(proposed->'parking_zones')='array'
      then jsonb_build_object('parking_zones',public.entries_upgrade(proposed->'parking_zones')) else '{}' end
  where status='pending' and jsonb_typeof(proposed)='object' and (proposed ? 'fee' or proposed ? 'parking_zones');

-- ===== 分區 area 移除（步驟 2） =====

-- Drops area from every zone a writer sends (old builds and imports still
-- do). Sorts before the fee_plans and zone_ids triggers, which match
-- stored zones by name.
create function public.drop_zone_area() returns trigger
language plpgsql set search_path='' as $$
begin
  if jsonb_typeof(new.parking_zones)='array' and exists(select 1 from jsonb_array_elements(new.parking_zones) z
      where jsonb_typeof(z)='object' and z ? 'area') then
    new.parking_zones:=(select jsonb_agg(case when jsonb_typeof(z)='object' then z-'area' else z end order by n)
      from jsonb_array_elements(new.parking_zones) with ordinality x(z,n));
  end if;
  return new;
end;
$$;
create trigger community_spots_drop_zone_area before insert or update on public.community_spots
  for each row execute function public.drop_zone_area();
create trigger official_heavy_spots_drop_zone_area before insert or update on public.official_heavy_spots
  for each row execute function public.drop_zone_area();

-- 202610310010's id trigger, matching zones by name alone.
create or replace function public.assign_entry_ids() returns trigger
language plpgsql set search_path='' as $$
begin
  new.parking_zones:=public.entries_with_ids(new.parking_zones,
    case when tg_op='UPDATE' then old.parking_zones end,array['name']);
  new.parking_segments:=public.entries_with_ids(new.parking_segments,
    case when tg_op='UPDATE' then old.parking_segments end,array['name','side']);
  return new;
end;
$$;

-- A plan's name leaves out vehicles that do not apply (#188 layer 2).
create or replace function public.fee_plan_name(p_fee jsonb) returns text
language sql immutable set search_path='' as $$
  select coalesce(string_agg(v.label,'' order by v.o),'')
    ||case (select count(distinct e.value->>'mode') from jsonb_each(p_fee) e
        where e.value->>'mode' not in ('same_as_scooter','same_as_car','not_applicable'))
      when 0 then case when exists(select 1 from jsonb_each(p_fee) e where e.value->>'mode' in ('same_as_scooter','same_as_car'))
        then '比照' else '不適用' end
      when 1 then (select case min(e.value->>'mode') when 'free' then '免費' when 'hourly' then '計時'
          when 'per_visit' then '計次' when 'by_time' then '時段' else '未確認' end
        from jsonb_each(p_fee) e where e.value->>'mode' not in ('same_as_scooter','same_as_car','not_applicable'))
      else '混合' end
  from (values ('scooter','機車',1),('heavy','重機',2),('car','汽車',3)) v(key,label,o)
  where p_fee ? v.key and p_fee->v.key->>'mode' is distinct from 'not_applicable';
$$;

-- ===== 路段費率與計費規則（步驟 3） =====

create or replace function public.fee_plans_sync(p_new jsonb,p_old jsonb) returns jsonb
language plpgsql immutable set search_path='' as $$
declare
  v_plans jsonb:=case when jsonb_typeof(p_new->'fee_plans')='array' then p_new->'fee_plans' end;
  v_fee jsonb:=nullif(p_new->'fee','null'::jsonb);
  v_plan text:=p_new->>'fee_plan';
  v_zones jsonb:=p_new->'parking_zones';
  v_new_zones jsonb:=case when jsonb_typeof(p_new->'parking_zones')='array' then p_new->'parking_zones' else '[]'::jsonb end;
  v_old_zones jsonb:=case when jsonb_typeof(p_old->'parking_zones')='array' then p_old->'parking_zones' else '[]'::jsonb end;
  v_same_plans boolean:=p_old is not null and (p_new->'fee_plans') is not distinct from (p_old->'fee_plans');
  -- What each zone does: 'copy' its plan's fee, 'take' its fee into a plan,
  -- 'clear' its reference, or 'keep'.
  v_acts text[]:='{}'; v_take_top boolean:=false; v_legacy boolean:=false;
  v_keep text[]:='{}'; v_taken jsonb:='[]'; v_out jsonb:='[]'; r jsonb; z jsonb; pf jsonb; i integer:=0;
  v_n bigint; v_old_zone jsonb; v_in_use jsonb;
  -- Plans the segments refer to (#188 layer 2): kept like the zones' and
  -- the spot's own; spot_fee_plans_sync() copies their fees.
  v_segments jsonb:=case when jsonb_typeof(p_new->'parking_segments')='array' then p_new->'parking_segments' else '[]'::jsonb end;
begin
  -- Plans that are not a list are left for the check to refuse.
  if p_new->'fee_plans' is not null and jsonb_typeof(p_new->'fee_plans') not in ('array','null') then
    return jsonb_build_object('fee',v_fee,'fee_plan',v_plan,'fee_plans',p_new->'fee_plans','parking_zones',v_zones);
  end if;

  -- A plan the writer removed while the spot, or a zone that keeps a fee,
  -- still refers to it: refused, never rebuilt under a generated name.
  if p_old is not null and not v_same_plans then
    select jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'zones',s.zones,'segments',s.segments,'spot',s.spot) order by s.n) into v_in_use
    from (
      select o->>'id' id,o->>'name' name,x.n,
        (select count(*) from jsonb_array_elements(v_new_zones) e
          where jsonb_typeof(e)='object' and e->>'fee_plan'=o->>'id'
            and coalesce(jsonb_typeof(e->'fee'),'null')<>'null' and e->'fee'<>'{}'::jsonb) zones,
        coalesce(v_plan=o->>'id',false) spot,
        (select count(*) from jsonb_array_elements(v_segments) e
          where jsonb_typeof(e)='object' and e->>'fee_plan'=o->>'id'
            and coalesce(jsonb_typeof(e->'fee'),'null')<>'null' and e->'fee'<>'{}'::jsonb) segments
      from jsonb_array_elements(case when jsonb_typeof(p_old->'fee_plans')='array' then p_old->'fee_plans' else '[]'::jsonb end)
        with ordinality x(o,n)
      where jsonb_typeof(o)='object' and jsonb_typeof(o->'id')='string'
        and not exists(select 1 from jsonb_array_elements(coalesce(v_plans,'[]')) e
          where jsonb_typeof(e)='object' and e->>'id'=o->>'id')
    ) s where s.zones>0 or s.segments>0 or s.spot;
    if v_in_use is not null then
      raise exception 'fee plan in use' using errcode='23503',
        detail=jsonb_build_object('plans',v_in_use)::text,
        hint='change the spot or zones that refer to the plan first';
    end if;
  end if;

  pf:=(select e->'fee' from jsonb_array_elements(coalesce(v_plans,'[]')) e where e->>'id'=v_plan limit 1);
  if v_plan is not null and pf is not null and (p_old is null or v_plan is distinct from p_old->>'fee_plan'
      or v_fee is not distinct from nullif(p_old->'fee','null'::jsonb)) then
    v_fee:=pf; v_keep:=v_keep||v_plan;
  elsif jsonb_typeof(v_fee)='object' and v_fee<>'{}'::jsonb then
    v_take_top:=true; v_legacy:=true; v_taken:=v_taken||jsonb_build_array(v_fee);
  elsif v_plan is null or pf is not null then
    v_legacy:=v_plan is not null; v_plan:=null;
  else
    v_keep:=v_keep||v_plan;
  end if;

  for z,v_n in select e,x.n from jsonb_array_elements(v_new_zones) with ordinality x(e,n) order by x.n loop
    pf:=case when jsonb_typeof(z)='object' and jsonb_typeof(z->'fee_plan')='string' then (select e->'fee'
      from jsonb_array_elements(coalesce(v_plans,'[]')) e where e->>'id'=z->>'fee_plan' limit 1) end;
    -- The stored zone of the same name (the k-th such zone for the
    -- k-th): a reference the writer changed is an explicit choice of plan,
    -- never a fee edit to take in. No stored match: a new zone.
    v_old_zone:=case when jsonb_typeof(z)='object' then (
      select o from jsonb_array_elements(v_old_zones) with ordinality y(o,m)
      where jsonb_typeof(o)='object' and (o->'name') is not distinct from (z->'name')
        and (o->'area') is not distinct from (z->'area')
      order by y.m offset (
        select count(*) from jsonb_array_elements(v_new_zones) with ordinality w(e,k)
        where w.k<v_n and jsonb_typeof(e)='object' and (e->'name') is not distinct from (z->'name')
          and (e->'area') is not distinct from (z->'area'))
      limit 1) end;
    if jsonb_typeof(z) is distinct from 'object' then v_acts:=v_acts||'keep'::text;
    elsif z ? 'fee_plan' and (coalesce(jsonb_typeof(z->'fee'),'null')='null' or z->'fee'='{}'::jsonb) then
      -- A cleared zone fee drops its reference (rule 1).
      v_acts:=v_acts||'clear'::text; v_legacy:=true;
    elsif pf is not null and not (v_same_plans and v_old_zone is not null
        and (z->'fee_plan') is not distinct from (v_old_zone->'fee_plan')
        and coalesce(jsonb_typeof(z->'fee'),'')='object' and z->'fee'<>pf) then
      v_acts:=v_acts||'copy'::text; v_keep:=v_keep||(z->>'fee_plan');
    elsif coalesce(jsonb_typeof(z->'fee'),'')='object' and z->'fee'<>'{}'::jsonb then
      v_acts:=v_acts||'take'::text; v_legacy:=true; v_taken:=v_taken||jsonb_build_array(z->'fee');
    else
      v_acts:=v_acts||'keep'::text;
      if z ? 'fee_plan' then v_keep:=v_keep||(z->>'fee_plan'); end if;
    end if;
  end loop;

  -- A write that knows nothing of plans: the plans it no longer refers to
  -- go first (a fee it brings finds its plan again by content), so a fee
  -- that replaces another takes over the freed id and name.
  v_keep:=v_keep||array(select e->>'fee_plan' from jsonb_array_elements(v_segments) e
    where jsonb_typeof(e)='object' and jsonb_typeof(e->'fee_plan')='string');
  if v_legacy then
    v_plans:=(select jsonb_agg(e order by n) from jsonb_array_elements(coalesce(v_plans,'[]')) with ordinality x(e,n)
      where (e->>'id')=any(v_keep) or exists(select 1 from jsonb_array_elements(v_taken) t where t=e->'fee'));
  end if;
  if v_take_top then
    r:=public.fee_plans_absorb(v_plans,v_fee); v_plans:=r->'plans'; v_plan:=r->>'id';
  end if;
  for z in select e from jsonb_array_elements(v_new_zones) with ordinality x(e,n) order by n loop
    i:=i+1;
    if v_acts[i]='copy' then
      z:=jsonb_set(z,'{fee}',(select e->'fee' from jsonb_array_elements(v_plans) e where e->>'id'=z->>'fee_plan' limit 1));
    elsif v_acts[i]='take' then
      r:=public.fee_plans_absorb(v_plans,z->'fee'); v_plans:=r->'plans';
      z:=jsonb_set(z,'{fee_plan}',to_jsonb(r->>'id'));
    elsif v_acts[i]='clear' then
      -- A JSON null fee goes too: valid_zones() takes no null fee.
      z:=case when z->'fee'='null'::jsonb then z-'fee_plan'-'fee' else z-'fee_plan' end;
    end if;
    v_out:=v_out||jsonb_build_array(z);
  end loop;
  if jsonb_typeof(v_zones)='array' then v_zones:=v_out; end if;
  if jsonb_typeof(v_plans)='array' and jsonb_array_length(v_plans)=0 then v_plans:=null; end if;
  return jsonb_build_object('fee',v_fee,'fee_plan',v_plan,'fee_plans',v_plans,'parking_zones',v_zones);
end;
$$;

-- A street spot's segments as written, each fee_plan reference resolved
-- against p_plans (#188 layer 2): a cleared fee drops its reference; a
-- reference the writer kept while changing the segment's fee, with the
-- plans unchanged, gives way to that fee (the segment keeps its own); any
-- other reference to an existing plan copies the plan's fee. A reference to
-- a plan that is gone is refused, as fee_plans_sync() refuses one in use.
create function public.segment_fee_plans_sync(p_segments jsonb,p_plans jsonb,p_old_segments jsonb,p_same_plans boolean) returns jsonb
language plpgsql immutable set search_path='' as $$
declare v jsonb:='[]'::jsonb; g jsonb; o jsonb; pf jsonb;
begin
  if jsonb_typeof(p_segments) is distinct from 'array' then return p_segments; end if;
  for g in select x from jsonb_array_elements(p_segments) with ordinality t(x,n) order by n loop
    if jsonb_typeof(g)='object' and g ? 'fee_plan' then
      if coalesce(jsonb_typeof(g->'fee'),'null')='null' or g->'fee'='{}'::jsonb then
        g:=g-'fee_plan'-case when g->'fee'='null'::jsonb then 'fee' else '' end;
      else
        pf:=(select e->'fee' from jsonb_array_elements(case when jsonb_typeof(p_plans)='array' then p_plans else '[]'::jsonb end) e
          where e->>'id'=g->>'fee_plan' limit 1);
        o:=(select x from jsonb_array_elements(case when jsonb_typeof(p_old_segments)='array' then p_old_segments else '[]'::jsonb end) x
          where jsonb_typeof(x)='object' and g ? 'id' and x->'id'=g->'id' limit 1);
        if pf is null then
          raise exception 'fee plan in use' using errcode='23503',
            detail=jsonb_build_object('plans',jsonb_build_array(jsonb_build_object(
              'id',g->>'fee_plan','zones',0,'segments',1,'spot',false)))::text,
            hint='change the segments that refer to the plan first';
        elsif p_same_plans and o is not null and (o->'fee_plan') is not distinct from (g->'fee_plan')
            and o->'fee' is not distinct from pf and g->'fee'<>pf then
          g:=g-'fee_plan';
        else
          g:=jsonb_set(g,'{fee}',pf);
        end if;
      end if;
    end if;
    v:=v||jsonb_build_array(g);
  end loop;
  return v;
end;
$$;

-- 202610270023's trigger, now also resolving the segments' plan references.
create or replace function public.spot_fee_plans_sync() returns trigger
language plpgsql set search_path='' as $$
declare r jsonb;
begin
  r:=public.fee_plans_sync(to_jsonb(new),case when tg_op='UPDATE' then to_jsonb(old) end);
  new.fee:=nullif(r->'fee','null'::jsonb);
  -- A fee the plans changed (an edited plan) keeps its text in step when
  -- the text was the old fee's sentence and the writer left it alone.
  if tg_op='UPDATE' and new.fee is distinct from old.fee and new.fee_note is not distinct from old.fee_note
     and jsonb_typeof(old.fee)='object' and old.fee_note=public.fee_note_of(old.fee) then
    new.fee_note:=public.fee_note_of(new.fee);
  end if;
  new.fee_plan:=r->>'fee_plan';
  new.fee_plans:=nullif(r->'fee_plans','null'::jsonb);
  new.parking_zones:=r->'parking_zones';
  new.parking_segments:=public.segment_fee_plans_sync(new.parking_segments,new.fee_plans,
    case when tg_op='UPDATE' then old.parking_segments end,
    tg_op='UPDATE' and new.fee_plans is not distinct from old.fee_plans);
  return new;
end;
$$;

alter table public.community_spots add constraint community_spots_segment_fee_plans_check
  check (public.valid_segment_fee_plans(fee_plans,parking_segments));
alter table public.official_heavy_spots add constraint official_heavy_spots_segment_fee_plans_check
  check (public.valid_segment_fee_plans(fee_plans,parking_segments));
-- Segments are a street spot's only (2026-10-31 decision): a lot keeps its
-- bays in zones.
alter table public.community_spots add constraint community_spots_segments_street_check
  check (parking_segments='[]'::jsonb or not public.condition_off_street(space_type,facility_type));
alter table public.official_heavy_spots add constraint official_heavy_spots_segments_street_check
  check (parking_segments='[]'::jsonb or not public.condition_off_street(space_type,facility_type));

-- ===== 資格跟格位走（步驟 5） =====

-- What a spot's entries say of one vehicle (#188 layer 2): 'true' when any
-- entry lets it park; otherwise, when p_complete and every entry states it,
-- 'not_stated' if one says so, else 'false'; otherwise null (the spot's
-- own flags stand). A zone states it by its condition's allow or, without
-- one, by its access; a segment by its condition's allow.
create function public.entries_eligibility(p_entries jsonb,p_vehicle text,p_complete boolean) returns text
language sql immutable set search_path='' as $$
  select case when count(*)=0 then null
    when bool_or(x.v='true'::jsonb) then 'true'
    when not p_complete or bool_or(x.v is null) then null
    when bool_or(x.v=public.parking_contract()->'eligibility'->'not_stated') then 'not_stated'
    else 'false' end
  from (select coalesce(e->'condition'->'allow'->p_vehicle,
      public.parking_contract()->'conversion'->'from_access'->(e->>'access')->'allow'->p_vehicle) v
    from jsonb_array_elements(case when jsonb_typeof(p_entries)='array' then p_entries else '[]'::jsonb end) e
    where jsonb_typeof(e)='object') x;
$$;

-- Keeps the spot-level flags (read by old builds and the map) in step with
-- the entries: a lot's zones, a street spot's segments. Sorts after
-- sync_not_stated() (…_eligibility) and before vehicle_verification. A
-- write that changes a flag the entries decide, without changing the
-- entries, is refused rather than silently undone: who may park is the
-- bays' to say (change the segment or zone).
create function public.spot_entries_eligibility() returns trigger
language plpgsql set search_path='' as $$
declare
  v_off boolean:=public.condition_off_street(new.space_type,new.facility_type);
  v_entries jsonb:=case when v_off then new.parking_zones else new.parking_segments end;
  v_complete boolean:=case when v_off then coalesce(new.zones_complete,false) else true end;
  s text:=public.entries_eligibility(v_entries,'scooter',v_complete);
  h text:=public.entries_eligibility(v_entries,'heavy',v_complete);
  v_same boolean:=tg_op='UPDATE' and v_entries is not distinct from
    (case when v_off then old.parking_zones else old.parking_segments end);
begin
  if v_same and (
    ((new.scooter_allowed is distinct from old.scooter_allowed or new.scooter_not_stated is distinct from old.scooter_not_stated)
      and s is not null and s is distinct from
        (case when new.scooter_not_stated then 'not_stated' else new.scooter_allowed::text end))
    or ((new.heavy_allowed is distinct from old.heavy_allowed or new.heavy_not_stated is distinct from old.heavy_not_stated)
      and h is not null and h is distinct from
        (case when new.heavy_not_stated then 'not_stated' else new.heavy_allowed::text end))) then
    raise exception 'eligibility follows the bays' using errcode='22023',
      detail=jsonb_build_object('scooter',s,'heavy',h)::text,
      hint='change who may park on the segment or zone';
  end if;
  if s in ('true','false') then new.scooter_allowed:=s::boolean; new.scooter_not_stated:=false;
  elsif s='not_stated' then new.scooter_allowed:=null; new.scooter_not_stated:=true; end if;
  if h in ('true','false') then new.heavy_allowed:=h::boolean; new.heavy_not_stated:=false;
  elsif h='not_stated' then new.heavy_allowed:=null; new.heavy_not_stated:=true; end if;
  return new;
end;
$$;
create trigger community_spots_eligibility_entries before insert or update on public.community_spots
  for each row execute function public.spot_entries_eligibility();
create trigger official_heavy_spots_eligibility_entries before insert or update on public.official_heavy_spots
  for each row execute function public.spot_entries_eligibility();

-- A street spot with a single segment: the spot's flags move onto it (the
-- segment then says who may park; the trigger keeps the spot's in step).
-- Plain updates, as above. More segments: left for an admin (要補填).
create function public.spot_allow_of(p_allowed boolean,p_not_stated boolean) returns jsonb
language sql immutable set search_path='' as $$
  select case when p_not_stated then public.parking_contract()->'eligibility'->'not_stated' else to_jsonb(p_allowed) end;
$$;
alter table public.community_spots disable trigger user;
alter table public.official_heavy_spots disable trigger user;
update public.community_spots set parking_segments=jsonb_build_array(jsonb_set(parking_segments->0,'{condition}',
    coalesce(parking_segments->0->'condition','{}'::jsonb)||jsonb_build_object('allow',jsonb_build_object(
      'scooter',public.spot_allow_of(scooter_allowed,scooter_not_stated),
      'heavy',public.spot_allow_of(heavy_allowed,heavy_not_stated)))))
  where jsonb_array_length(parking_segments)=1 and not coalesce(parking_segments->0->'condition' ? 'allow',false)
    and (scooter_allowed is not null or scooter_not_stated) and (heavy_allowed is not null or heavy_not_stated)
    and not (coalesce(scooter_allowed,false) and parking_segments->0->'condition'->>'bay'='heavy');
update public.official_heavy_spots set parking_segments=jsonb_build_array(jsonb_set(parking_segments->0,'{condition}',
    coalesce(parking_segments->0->'condition','{}'::jsonb)||jsonb_build_object('allow',jsonb_build_object(
      'scooter',public.spot_allow_of(scooter_allowed,scooter_not_stated),
      'heavy',public.spot_allow_of(heavy_allowed,heavy_not_stated)))))
  where jsonb_array_length(parking_segments)=1 and not coalesce(parking_segments->0->'condition' ? 'allow',false)
    and (scooter_allowed is not null or scooter_not_stated) and (heavy_allowed is not null or heavy_not_stated)
    and not (coalesce(scooter_allowed,false) and parking_segments->0->'condition'->>'bay'='heavy');
alter table public.community_spots enable trigger user;
alter table public.official_heavy_spots enable trigger user;

